SELECT settlement_id, merchant_id, settlement_date, total_sales, total_received, difference, status, created_at
FROM settlement_record
WHERE merchant_id = #{merchantId}
  AND settlement_date = #{settlementDate}

SELECT settlement_id, merchant_id, settlement_date, total_sales, total_received, difference, status, created_at
FROM settlement_record
WHERE merchant_id = #{merchantId}
ORDER BY settlement_date DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM settlement_record
WHERE merchant_id = #{merchantId}
